fn smallest_num(nums: &Vec<i32>) -> i32 {
    // Since the input vector is guaranteed to be non-empty,
    // we can safely initialize `min` with the first element.
    let mut min = nums[0];
    
    // Iterate over the rest of the elements and update `min` whenever
    // we find a smaller value.
    for &num in nums.iter().skip(1) {
        if num < min {
            min = num;
        }
    }
    
    min
}